function nativeBudgetAnalysis(){if(!project)return {peak:0,first:null,frames:[]};let result={peak:0,first:null,frames:[]};for(let index=0;index<project.sections.length;index++){let frames;if(index===section)frames=nativeActorFrames;else{frames=[];const trace=new NativeMotion();for(const key of ['bonusConditions','routeChoice','missedSearchlight','arrivalOrigin','handAttachment'])trace[key]=motion[key];trace.onPreviewFrame=state=>{frames[state.frame]=ActorBudget.nativeCount(state);};trace.sync(project,index,Math.max(10000,...project.sections[index].placements.map(o=>o.zPos1)));}const check=ActorBudget.fromNative(frames);result.peak=Math.max(result.peak,check.peak);if(result.first===null&&check.first!==null){result.first=check.first;result.section=index;}}return result;}

